class Solution:
    def maxAlternatingSum(self, nums: List[int], swaps: List[List[int]]) -> int:
        n = len(nums)
        adj = [[] for _ in range(n)]
        for p, q in swaps:
            adj[p].append(q)
            adj[q].append(p)
        comp = [-1] * n
        cid = 0
        for s in range(n):
            if comp[s] != -1:
                continue
            stack = [s]
            comp[s] = cid
            while stack:
                u = stack.pop()
                for v in adj[u]:
                    if comp[v] == -1:
                        comp[v] = cid
                        stack.append(v)
            cid += 1
        groups = [[] for _ in range(cid)]
        evens = [0] * cid
        for i, x in enumerate(nums):
            groups[comp[i]].append(x)
            if i % 2 == 0:
                evens[comp[i]] += 1
        ans = 0
        for g, e in zip(groups, evens):
            g.sort(reverse=True)
            ans += sum(g[:e]) - sum(g[e:])
        return ans

