class Solution {
    public long maxAlternatingSum(int[] nums, int[][] swaps) {
        int n = nums.length;
        List<List<Integer>> adj = new ArrayList<>();
        for (int i = 0; i < n; i++) adj.add(new ArrayList<>());
        for (int[] s : swaps) { adj.get(s[0]).add(s[1]); adj.get(s[1]).add(s[0]); }
        int[] comp = new int[n];
        Arrays.fill(comp, -1);
        int cid = 0;
        for (int s = 0; s < n; s++) {
            if (comp[s] != -1) continue;
            Deque<Integer> st = new ArrayDeque<>();
            st.push(s); comp[s] = cid;
            while (!st.isEmpty()) {
                int u = st.pop();
                for (int v : adj.get(u)) if (comp[v] == -1) { comp[v] = cid; st.push(v); }
            }
            cid++;
        }
        List<List<Long>> groups = new ArrayList<>();
        int[] evens = new int[cid];
        for (int i = 0; i < cid; i++) groups.add(new ArrayList<>());
        for (int i = 0; i < n; i++) {
            groups.get(comp[i]).add((long) nums[i]);
            if (i % 2 == 0) evens[comp[i]]++;
        }
        long ans = 0;
        for (int c = 0; c < cid; c++) {
            groups.get(c).sort(Collections.reverseOrder());
            int e = evens[c];
            for (int j = 0; j < groups.get(c).size(); j++)
                ans += (j < e ? groups.get(c).get(j) : -groups.get(c).get(j));
        }
        return ans;
    }
}

