    const adj = Array.from({length: n}, () => []);
    for (const [p, q] of swaps) { adj[p].push(q); adj[q].push(p); }
    const comp = new Array(n).fill(-1);
    let cid = 0;
    for (let s = 0; s < n; s++) {
        if (comp[s] !== -1) continue;
        const st = [s];
        comp[s] = cid;
        while (st.length) {
            const u = st.pop();
            for (const v of adj[u]) if (comp[v] === -1) { comp[v] = cid; st.push(v); }
        }
        cid++;
    }
    const groups = Array.from({length: cid}, () => []);
    const evens = new Array(cid).fill(0);
    for (let i = 0; i < n; i++) {
        groups[comp[i]].push(nums[i]);
        if (i % 2 === 0) evens[comp[i]]++;
