class Solution {
    private int[] parent;
    private int find(int x) { while (parent[x] != x) { parent[x] = parent[parent[x]]; x = parent[x]; } return x; }
    public long maxAlternatingSum(int[] nums, int[][] swaps) {
        int n = nums.length;
        parent = new int[n];
        for (int i = 0; i < n; i++) parent[i] = i;
        for (int[] s : swaps) parent[find(s[0])] = find(s[1]);
        Map<Integer, List<Long>> groups = new HashMap<>();
        Map<Integer, Integer> evens = new HashMap<>();
        for (int i = 0; i < n; i++) {
            int r = find(i);
            groups.computeIfAbsent(r, k -> new ArrayList<>()).add((long) nums[i]);
            if (i % 2 == 0) evens.merge(r, 1, Integer::sum);
        }
        long ans = 0;
        for (var entry : groups.entrySet()) {
            List<Long> g = entry.getValue();
            g.sort(Collections.reverseOrder());
            int e = evens.getOrDefault(entry.getKey(), 0);
            for (int j = 0; j < g.size(); j++) ans += (j < e ? g.get(j) : -g.get(j));
        }
        return ans;
    }
}

